def redact_text(text: str) -> str:
    out = text
    for secret in _secrets:
        if secret:
            out = out.replace(secret, "[REDACTED]")
    for hdr in SENSITIVE_HEADERS:
        pattern = re.compile(
            rf"({re.escape(hdr)}:\s*)([^\r\n]+)",
            re.IGNORECASE,
        )
        out = pattern.sub(r"\1[REDACTED]", out)
    return out

